def evaluate_gates(
    candidate_auc: float,
    min_auc: float,
    champion_auc: float | None,
    max_regression: float,
) -> list[tuple[str, bool, str]]:
    """Quality threshold and champion comparison. Returns (name, passed, detail) rows."""
    gates = [
        ("quality_threshold", candidate_auc >= min_auc, f"auc={candidate_auc:.4f} min={min_auc:.4f}")
    ]
    if champion_auc is None:
        gates.append(("champion_comparison", True, "no current champion"))
    else:
        floor = champion_auc - max_regression
        gates.append(
            (
                "champion_comparison",
                candidate_auc >= floor,
                f"candidate={candidate_auc:.4f} champion={champion_auc:.4f} allowed_regression={max_regression:.4f}",
            )
        )
    return gates

def wait_ready(w: WorkspaceClient, name: str) -> dict:
    deadline = time.time() + READY_TIMEOUT_S
    while time.time() < deadline:
        state = endpoint_state(w, name)["state"]
        ready, update = state.get("ready"), state.get("config_update")
        print(f"endpoint {name}: ready={ready} config_update={update}")
        if update == "UPDATE_FAILED":
            raise SystemExit(f"Endpoint update failed: {state}")
        if ready == "READY" and update == "NOT_UPDATING":
            return endpoint_state(w, name)
        time.sleep(30)
    raise SystemExit(f"Endpoint {name} not READY after {READY_TIMEOUT_S}s")

