        if TAG in tags and settings.schedule is not None:
            found.append(
                {
                    "job_id": job.job_id,
                    "job_name": settings.name,
                    "tag_value": tags[TAG],
                    "schedule_status": settings.schedule.pause_status.value if settings.schedule.pause_status else "UNPAUSED",
